// The bundled beginner list is generated by scripts/rank-beginner-anime.mjs.
export type BeginnerSeries = {
  id: number;
  title: string;
  titleJa: string;
  titleEn: string;
  url: string;
  type: string;
  poster: string;
  year?: number;
  episodes?: number;
  japaneseEpisodes: number;
  genres: string[];
  firstEpisode: string;
  /** Word ids (see wordId) of the 50 most frequent learnable words. */
  topWords: string[];
  wordsPerMinute: number;
  /** Distinct words that cover 90% of the dialogue, per 24 minutes. */
  wordsFor90: number;
  /** 0 (easiest on the site) to 100. */
  difficulty: number;
  coreShare: number;
  unknownShare: number;
};

/** Where a series sits among every ranked series on the site. */
export function levelOf(index: number, ranked: number) {
  const share = ranked > 1 ? index / (ranked - 1) : 0;
  if (share < 0.05) return { key: 'start', label: 'Start here' };
  if (share < 0.12) return { key: 'next', label: 'Next step' };
  return { key: 'later', label: 'A bit harder' };
}

/** Words a minute while someone is talking: about a tenth of the site's series are below 115, a third below 145. */
export function describePace(wordsPerMinute: number) {
  if (wordsPerMinute < 115) return 'Slow speech';
  if (wordsPerMinute < 145) return 'Moderate speech';
  return 'Fast speech';
}
